cli-octal-to-symbolic.solution:
def octal_to_symbolic(mode):
    n = int(mode, 8)
    chars = []
    for shift in (6, 3, 0):
        bits = (n >> shift) & 7
        chars.append("r" if bits & 4 else "-")
        chars.append("w" if bits & 2 else "-")
        chars.append("x" if bits & 1 else "-")
    special = (n >> 9) & 7
    for bit, pos, letter in ((4, 2, "s"), (2, 5, "s"), (1, 8, "t")):
        if special & bit:
            chars[pos] = letter if chars[pos] == "x" else letter.upper()
    return "".join(chars)

cli-symbolic-to-octal.solution:
def symbolic_to_octal(perms):
    if len(perms) == 10:
        perms = perms[1:]
    digits = [0, 0, 0]
    special = 0
    special_bit = (4, 2, 1)
    for cls in range(3):
        r, w, x = perms[cls * 3: cls * 3 + 3]
        if r == "r":
            digits[cls] += 4
        if w == "w":
            digits[cls] += 2
        if x in "xst":
            digits[cls] += 1
        if x in "sStT":
            special += special_bit[cls]
    return str(special) + "".join(str(d) for d in digits)

cli-chmod-apply.solution:
def apply_chmod(mode, expr):
    n = int(mode, 8)
    shift = {"u": 6, "g": 3, "o": 0}
    value = {"r": 4, "w": 2, "x": 1}
    for clause in expr.split(","):
        i = 0
        while i < len(clause) and clause[i] in "ugoa":
            i += 1
        who, op, perms = clause[:i], clause[i], clause[i + 1:]
        classes = set()
        for c in who or "a":
            classes.update("ugo" if c == "a" else c)
        bits = 0
        for p in perms:
            bits |= value[p]
        for c in classes:
            s = shift[c]
            if op == "+":
                n |= bits << s
            elif op == "-":
                n &= ~(bits << s)
            else:
                n = (n & ~(7 << s)) | (bits << s)
    return format(n & 0o777, "03o")

cli-umask-result.solution:
def umask_result(umask, kind):
    base = 0o666 if kind == "file" else 0o777
    mask = int(umask, 8) & 0o777
    return format(base & ~mask, "03o")

cli-normalize-path.solution:
def resolve_path(cwd, path):
    full = path if path.startswith("/") else cwd + "/" + path
    stack = []
    for part in full.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return "/" + "/".join(stack)

cli-glob-match.solution:
def glob_match(pattern, name):
    tokens = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == "*":
            tokens.append(("star",))
            i += 1
        elif c == "?":
            tokens.append(("any",))
            i += 1
        elif c == "[":
            j = i + 1
            negate = pattern[j] in "!^"
            if negate:
                j += 1
            k = pattern.index("]", j)
            body = pattern[j:k]
            singles, ranges = set(), []
            m = 0
            while m < len(body):
                if m + 2 < len(body) and body[m + 1] == "-":
                    ranges.append((body[m], body[m + 2]))
                    m += 3
                else:
                    singles.add(body[m])
                    m += 1
            tokens.append(("set", negate, singles, ranges))
            i = k + 1
        else:
            tokens.append(("lit", c))
            i += 1

    def one(tok, ch):
        if tok[0] == "any":
            return True
        if tok[0] == "lit":
            return tok[1] == ch
        _, negate, singles, ranges = tok
        hit = ch in singles or any(lo <= ch <= hi for lo, hi in ranges)
        return hit != negate

    n = len(name)
    reach = [True] + [False] * n          # reach[j]: tokens so far can consume name[:j]
    for tok in tokens:
        nxt = [False] * (n + 1)
        if tok[0] == "star":
            seen = False
            for j in range(n + 1):
                seen = seen or reach[j]
                nxt[j] = seen
        else:
            for j in range(n):
                if reach[j] and one(tok, name[j]):
                    nxt[j + 1] = True
        reach = nxt
    return reach[n]

cli-brace-expansion.solution:
import re

def brace_expand(s):
    start = s.find("{")
    if start == -1:
        return [s]
    depth = 0
    for end in range(start, len(s)):
        if s[end] == "{":
            depth += 1
        elif s[end] == "}":
            depth -= 1
            if depth == 0:
                break
    prefix, body, rest = s[:start], s[start + 1:end], s[end + 1:]
    parts, cur, depth = [], "", 0
    for ch in body:
        if ch == "," and depth == 0:
            parts.append(cur)
            cur = ""
            continue
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
        cur += ch
    parts.append(cur)
    if len(parts) == 1:
        m = re.fullmatch(r"(-?\d+)\.\.(-?\d+)", body)
        lo, hi = int(m.group(1)), int(m.group(2))
        step = 1 if lo <= hi else -1
        middles = [str(v) for v in range(lo, hi + step, step)]
    else:
        middles = []
        for part in parts:
            middles.extend(brace_expand(part))
    tails = brace_expand(rest)
    return [prefix + mid + tail for mid in middles for tail in tails]

cli-tokenize-command.solution:
def shell_split(line):
    words, cur, in_word = [], [], False
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in " \t":
            if in_word:
                words.append("".join(cur))
                cur, in_word = [], False
            i += 1
        elif c == "'":
            j = line.index("'", i + 1)
            cur.append(line[i + 1:j])
            in_word = True
            i = j + 1
        elif c == '"':
            in_word = True
            i += 1
            while line[i] != '"':
                if line[i] == "\\" and line[i + 1] in '"\\$`':
                    cur.append(line[i + 1])
                    i += 2
                else:
                    cur.append(line[i])
                    i += 1
            i += 1
        elif c == "\\":
            cur.append(line[i + 1])
            in_word = True
            i += 2
        else:
            cur.append(c)
            in_word = True
            i += 1
    if in_word:
        words.append("".join(cur))
    return words

cli-parameter-expansion.solution:
def expand_params(template, args, env):
    def lookup(key):
        if key.isdigit():
            k = int(key)
            return args[k - 1] if 1 <= k <= len(args) else ""
        return env.get(key, "")

    def is_name_char(ch):
        return ch == "_" or ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ("0" <= ch <= "9")

    out, i, n = [], 0, len(template)
    while i < n:
        c = template[i]
        if c != "$" or i + 1 == n:
            out.append(c)
            i += 1
            continue
        d = template[i + 1]
        if d == "{":
            j = template.index("}", i)
            body = template[i + 2:j]
            i = j + 1
            if body.startswith("#"):
                out.append(str(len(lookup(body[1:]))))
            elif ":-" in body:
                key, word = body.split(":-", 1)
                out.append(lookup(key) or word)
            elif ":+" in body:
                key, word = body.split(":+", 1)
                out.append(word if lookup(key) else "")
            else:
                out.append(lookup(body))
        elif "1" <= d <= "9":
            out.append(lookup(d))
            i += 2
        elif d == "#":
            out.append(str(len(args)))
            i += 2
        elif d in "*@":
            out.append(" ".join(args))
            i += 2
        elif is_name_char(d) and not d.isdigit():
            j = i + 1
            while j < n and is_name_char(template[j]):
                j += 1
            out.append(lookup(template[i + 1:j]))
            i = j
        else:
            out.append("$")
            i += 1
    return "".join(out)

cli-test-expression.solution:
def test_eval(args, files):
    BIN = {"=", "!=", "-eq", "-ne", "-lt", "-le", "-gt", "-ge"}
    UN = {"-z", "-n", "-e", "-f", "-d"}
    pos = 0

    def primary():
        nonlocal pos
        if pos + 2 < len(args) and args[pos + 1] in BIN:
            a, op, b = args[pos], args[pos + 1], args[pos + 2]
            pos += 3
            if op == "=":
                return a == b
            if op == "!=":
                return a != b
            x, y = int(a), int(b)
            return {"-eq": x == y, "-ne": x != y, "-lt": x < y,
                    "-le": x <= y, "-gt": x > y, "-ge": x >= y}[op]
        if args[pos] in UN and pos + 1 < len(args):
            op, a = args[pos], args[pos + 1]
            pos += 2
            if op == "-z":
                return a == ""
            if op == "-n":
                return a != ""
            if op == "-e":
                return a in files
            if op == "-f":
                return files.get(a) == "f"
            return files.get(a) == "d"
        s = args[pos]
        pos += 1
        return s != ""

    def negation():
        nonlocal pos
        if pos < len(args) and args[pos] == "!" and pos + 1 < len(args):
            pos += 1
            return not negation()
        return primary()

    def conjunction():
        nonlocal pos
        value = negation()
        while pos < len(args) and args[pos] == "-a":
            pos += 1
            rhs = negation()
            value = value and rhs
        return value

    def disjunction():
        nonlocal pos
        value = conjunction()
        while pos < len(args) and args[pos] == "-o":
            pos += 1
            rhs = conjunction()
            value = value or rhs
        return value

    if not args:
        return 1
    return 0 if disjunction() else 1

cli-top-k-lines.solution:
def top_k(lines, k):
    counts = {}
    for line in lines:
        counts[line] = counts.get(line, 0) + 1
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return [[c, line] for line, c in ranked[:k]]

cli-cut-fields.solution:
def cut_fields(lines, delim, spec):
    ranges = []
    for item in spec.split(","):
        if "-" in item:
            lo, hi = item.split("-")
            ranges.append((int(lo) if lo else 1, int(hi) if hi else None))
        else:
            ranges.append((int(item), int(item)))

    def wanted(n):
        return any(lo <= n and (hi is None or n <= hi) for lo, hi in ranges)

    out = []
    for line in lines:
        if delim not in line:
            out.append(line)
            continue
        fields = line.split(delim)
        out.append(delim.join(f for i, f in enumerate(fields, 1) if wanted(i)))
    return out

cli-tr-translate.solution:
def tr(text, set1, set2, delete):
    def expand(spec):
        out, i = [], 0
        while i < len(spec):
            if i + 2 < len(spec) and spec[i + 1] == "-":
                out.extend(chr(c) for c in range(ord(spec[i]), ord(spec[i + 2]) + 1))
                i += 3
            else:
                out.append(spec[i])
                i += 1
        return out

    src = expand(set1)
    if delete:
        drop = set(src)
        return "".join(ch for ch in text if ch not in drop)
    dst = expand(set2)
    if len(dst) < len(src):
        dst += [dst[-1]] * (len(src) - len(dst))
    table = {}
    for a, b in zip(src, dst):
        table[a] = b
    return "".join(table.get(ch, ch) for ch in text)

cli-head-tail.solution:
def head_tail(lines, tool, n):
    size = len(lines)
    if tool == "head":
        if n.startswith("-"):
            keep = max(0, size - int(n[1:]))
        else:
            keep = int(n)
        return lines[:keep]
    if n.startswith("+"):
        start = max(0, int(n[1:]) - 1)
        return lines[start:]
    k = int(n)
    return lines[max(0, size - k):]

cli-sed-substitute.solution:
import re

def sed_s(lines, script):
    total = len(lines)
    if script.startswith("/"):
        end = script.index("/", 1)
        needle = script[1:end]
        command = script[end + 1:]
        selected = lambda num, line: needle in line
    else:
        m = re.match(r"(\d+|\$)?(?:,(\d+|\$))?", script)
        first, second = m.group(1), m.group(2)
        command = script[m.end():]
        if first is None:
            selected = lambda num, line: True
        else:
            lo = total if first == "$" else int(first)
            if second is None:
                hi = lo
            else:
                hi = total if second == "$" else int(second)
            selected = lambda num, line: lo <= num <= hi
    _, old, new, flag = command.split("/")
    count = -1 if flag == "g" else 1
    out = []
    for num, line in enumerate(lines, 1):
        out.append(line.replace(old, new, count) if selected(num, line) else line)
    return out

cli-join-on-key.solution:
def join_lines(left, right):
    out = []
    i = j = 0
    while i < len(left) and j < len(right):
        lf, rf = left[i].split(" "), right[j].split(" ")
        if lf[0] < rf[0]:
            i += 1
        elif lf[0] > rf[0]:
            j += 1
        else:
            key = lf[0]
            i_end = i
            while i_end < len(left) and left[i_end].split(" ")[0] == key:
                i_end += 1
            j_end = j
            while j_end < len(right) and right[j_end].split(" ")[0] == key:
                j_end += 1
            for a in range(i, i_end):
                for b in range(j, j_end):
                    fields = [key] + left[a].split(" ")[1:] + right[b].split(" ")[1:]
                    out.append(" ".join(fields))
            i, j = i_end, j_end
    return out

cli-xargs-batches.solution:
def xargs_batches(command, items, max_args, max_chars):
    out = []
    line, count = command, 0
    for item in items:
        fits = count < max_args and len(line) + 1 + len(item) <= max_chars
        if count > 0 and not fits:
            out.append(line)
            line, count = command, 0
        line += " " + item
        count += 1
    if count:
        out.append(line)
    return out

cli-cron-match.solution:
def cron_match(expr, minute, hour, dom, month, dow):
    bounds = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]
    fields = expr.split()

    def values(field, lo, hi):
        allowed = set()
        for item in field.split(","):
            step = 1
            if "/" in item:
                item, s = item.split("/")
                step = int(s)
            if item == "*":
                a, b = lo, hi
            elif "-" in item:
                x, y = item.split("-")
                a, b = int(x), int(y)
            else:
                a = b = int(item)
            allowed.update(range(a, b + 1, step))
        return allowed

    sets = [values(f, lo, hi) for f, (lo, hi) in zip(fields, bounds)]
    if 7 in sets[4]:
        sets[4].add(0)
    if not (minute in sets[0] and hour in sets[1] and month in sets[3]):
        return False
    dom_ok, dow_ok = dom in sets[2], dow in sets[4]
    if fields[2] == "*" or fields[4] == "*":
        return dom_ok and dow_ok
    return dom_ok or dow_ok

cli-du-rollup.solution:
def du_rollup(files):
    totals = {".": 0}
    for path, size in files:
        totals["."] += size
        parts = path.split("/")[:-1]
        for depth in range(1, len(parts) + 1):
            d = "/".join(parts[:depth])
            totals[d] = totals.get(d, 0) + size
    return sorted(([t, d] for d, t in totals.items()), key=lambda p: (-p[0], p[1]))

cli-find-filter.solution:
import fnmatch
import math

def find_filter(entries, criteria):
    def compare(value, spec):
        if spec[0] == "+":
            return value > int(spec[1:])
        if spec[0] == "-":
            return value < int(spec[1:])
        return value == int(spec)

    out = []
    for e in entries:
        if "name" in criteria:
            base = e["path"].rsplit("/", 1)[-1]
            if not fnmatch.fnmatchcase(base, criteria["name"]):
                continue
        if "type" in criteria and e["type"] != criteria["type"]:
            continue
        if "size" in criteria:
            spec = criteria["size"]
            unit = {"c": 1, "k": 1024, "M": 1048576}[spec[-1]]
            units = math.ceil(e["size"] / unit)
            if not compare(units, spec[:-1]):
                continue
        if "mtime" in criteria:
            days = int(e["age_hours"] // 24)
            if not compare(days, criteria["mtime"]):
                continue
        out.append(e["path"])
    return out
